# Find colored pixels by block (2s and 3s only)
pixels_by_block = {}
for r in range(H):
    parts = test_input.splitlines()[r].split()
    for c, val in enumerate(parts):
        v = int(val)
        if v in (2, 3):
            br = sum(1 for sr in sep_rows if sr < r)
            bc = sum(1 for sc in sep_cols if sc < c)
            if (br, bc) not in pixels_by_block:
                pixels_by_block[(br, bc)] = []
            pixels_by_block[(br, bc)].append((r, c, v))

print("Pixels by block:")
for k, pxls in sorted(pixels_by_block.items()):
    vals = set(p[2] for p in pxls)
    print(f"  Block {k}: {vals}")

# Determine row/col activations (set of colors for each)
row_vals = {}
for (br, bc), pxls in pixels_by_block.items():
    vals = set(p[2] for p in pxls)
    # Mark that row br has these color values
    if br not in row_vals:
        row_vals[br] = set()
    row_vals[br].update(vals)
    # Mark that col bc has these color values
    if bc not in col_vals:
        col_vals[bc] = set()
    col_vals[bc].update(vals)

print("\nRow activations:", row_vals)
print("Col activations:", col_vals)

# Build output grid
out = [[0]*W for _ in range(H)]

# First add separators
for r in range(H):
    parts = test_input.splitlines()[r].split()
    for c, val in enumerate(parts):
        if int(val) == 8:
            out[r][c] = 8

# Fill non-separator cells based on rules
for r in range(H):
    for c in range(W):
        if r in sep_rows or c in sep_cols:
            continue

        br = sum(1 for sr in sep_rows if sr < r)
        bc = sum(1 for sc in sep_cols if sc < c)

        rv = row_vals.get(br, None)
        cv = col_vals.get(bc, None)

        if rv is not None and cv is not None:
            if rv == cv:
                out[r][c] = list(rv)[0]
            else:
                out[r][c] = 6
        elif rv is not None:
            out[r][c] = list(rv)[0]
        elif cv is not None:
            out[r][c] = list(cv)[0]
        else:
            out[r][c] = 0

# Print output
output_lines = [' '.join(map(str, row)) for row in out]
print("\n=== OUTPUT ===")
for i, line in enumerate(output_lines[:15]):
    print(f"{i}: {line}")
print("...")
for i, line in enumerate(output_lines[-3:], start=len(output_lines)-3):
    print(f"{len(output_lines)-3+i}: {line}")

